import React from 'react';
import { TopSpin } from './index';

const previews = {
  componentName: 'TopSpin',
  importPath: 'components/TopSpin',
  previews: [
    { name: '3D rig', description: "Top Spin: magenta gondola row somersaulting between swinging arms (TOPSP1).", render: () => <TopSpin /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Top Spin matched to the RCT2 TOPSP1 sprite: a wide MAGENTA gondola row hung
// between two counter-swinging support arms on A-frame towers — the arms swing
// while the gondola somersaults, riders' arms up.
export function TopSpin() {
  return (
    <Stage
      distance={8}
      targetY={1.6}
      build={(t, g) => {
        const MAGENTA = 0xb01050; // gondola (sprite #a01050)
        const RED = 0xb03428;
        const ORANGE = 0xe8641c;
        // twin towers
        [-1, 1].forEach((s) => {
          const x = s * 1.7;
          g.add(box(t, [0.6, 0.25, 1.6], 0x8a8f98, [x, 0.12, 0], { tex: 'concrete', repeat: [2, 5], rough: 0.9 }));
          [-0.5, 0.5].forEach((z) => g.add(box(t, [0.16, 2.6, 0.16], RED, [x, 1.3, z * 0.9], { tex: 'metal', metal: 0.4, rough: 0.5, rotZ: -s * 0.14 })));
          g.add(box(t, [0.16, 0.9, 0.16], RED, [x - s * 0.18, 2.5, 0], { metal: 0.4, rough: 0.5 }));
        });
        // arms + gondola
        const armL = new t.Group();
        armL.position.set(-1.42, 2.6, 0);
        g.add(armL);
        const armR = new t.Group();
        armR.position.set(1.42, 2.6, 0);
        g.add(armR);
        [armL, armR].forEach((arm, ai) => arm.add(box(t, [0.18, 1.7, 0.24], ai ? RED : RED, [0, -0.85, 0], { tex: 'metal', metal: 0.4, rough: 0.5 })));
        const gondola = new t.Group();
        gondola.position.y = -1.7;
        armL.add(gondola); // carried by the left arm; right arm mirrors visually
        gondola.add(box(t, [2.7, 0.5, 0.6], MAGENTA, [1.42, 0, 0], { tex: 'plastic', repeat: [8, 1], rough: 0.45 }));
        gondola.add(box(t, [2.7, 0.12, 0.7], ORANGE, [1.42, -0.3, 0], { rough: 0.5 })); // footrest rail
        // two rows of riders w/ shoulder bars
        for (let r = 0; r < 2; r++)
          for (let i = 0; i < 4; i++) {
            const p = buildPeep(t, { skin: SKIN_TONES[(r * 4 + i) % SKIN_TONES.length], shirt: SHIRTS[(r * 4 + i) % SHIRTS.length], seated: true, expression: 'surprised' });
            p.group.scale.setScalar(0.34);
            p.group.position.set(0.55 + i * 0.58, 0.08, r === 0 ? 0.18 : -0.18);
            if (r === 1) p.group.rotation.y = Math.PI;
            gondola.add(p.group);
          }
        gondola.add(box(t, [2.5, 0.05, 0.05], 0x24242a, [1.42, 0.42, 0.3], { metal: 0.5, rough: 0.4 }));
        gondola.add(box(t, [2.5, 0.05, 0.05], 0x24242a, [1.42, 0.42, -0.3], { metal: 0.5, rough: 0.4 }));
        return (time) => {
          const swing = Math.sin(time * 0.9) * 0.9;
          armL.rotation.z = swing;
          armR.rotation.z = swing;
          gondola.rotation.z = Math.sin(time * 0.9 + 1.2) * 1.6 - swing; // somersault counter-phase
        };
      }}
    />
  );
}

import React from 'react';
import { RiverRapids } from './index';

const previews = {
  componentName: 'RiverRapids',
  importPath: 'components/RiverRapids',
  previews: [
    { name: '3D rig', description: "River rapids: round orange raft with tyre tube bobbing down a rocky channel (RAPBOAT).", render: () => <RiverRapids /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// River rapids matched to the RCT2 RAPBOAT sprite: a round ORANGE raft with a
// black tyre-tube ring and SIX pink-backed seats around a central hub, bobbing
// and spinning down a rocky whitewater channel.
export function RiverRapids() {
  return (
    <Stage
      distance={7}
      targetY={0.5}
      background="#bfe6f2"
      build={(t, g) => {
        const ORANGE = 0xe8641c;
        const PINK = 0xd6338c;
        // channel: rocky banks + water strip
        g.add(box(t, [2.2, 0.14, 7], 0x2a6f9e, [0, 0.07, 0], { rough: 0.3, emissive: 0x123a55, opacity: 0.95 })); // water
        [-1.35, 1.35].forEach((x) => {
          g.add(box(t, [0.5, 0.5, 7], 0x8a8478, [x, 0.25, 0], { tex: 'concrete', repeat: [2, 20], rough: 0.95 }));
          for (let z = -3; z <= 3; z += 1.2) g.add(ball(t, 0.22, 0x76746c, [x * 0.92, 0.5, z], { tex: 'concrete', repeat: [2, 2], flat: true, rough: 1 }));
        });
        // white-water foam patches
        for (let z = -3; z <= 3; z += 0.8) g.add(box(t, [1.8, 0.02, 0.2], 0xdff2f8, [Math.sin(z * 2) * 0.3, 0.15, z], { rough: 0.4, opacity: 0.7, rotY: Math.sin(z) * 0.3 }));

        const raft = new t.Group();
        g.add(raft);
        // tyre tube + orange deck + hub
        const tube = new t.Mesh(new t.TorusGeometry(0.62, 0.16, 10, 24), new t.MeshStandardMaterial({ color: 0x1c1c20, roughness: 0.85 }));
        tube.rotation.x = -Math.PI / 2;
        tube.position.y = 0.16;
        raft.add(tube);
        raft.add(cyl(t, 0.6, 0.6, 0.1, ORANGE, [0, 0.2, 0], { tex: 'plastic', repeat: [8, 1], rough: 0.5, seg: 22 }));
        raft.add(cyl(t, 0.16, 0.2, 0.3, ORANGE, [0, 0.4, 0], { tex: 'plastic', rough: 0.5, seg: 14 })); // hub
        // six outward-facing seats with pink backs
        for (let i = 0; i < 6; i++) {
          const a = (i / 6) * Math.PI * 2;
          const seat = new t.Group();
          seat.position.set(Math.cos(a) * 0.38, 0.26, Math.sin(a) * 0.38);
          seat.rotation.y = -a - Math.PI / 2;
          seat.add(box(t, [0.24, 0.3, 0.05], PINK, [0, 0.16, -0.1], { rough: 0.55 }));
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i % SHIRTS.length], seated: true, expression: i % 2 ? 'happy' : 'surprised' });
          p.group.scale.setScalar(0.3);
          p.group.position.set(0, -0.14, 0.02);
          seat.add(p.group);
          raft.add(seat);
        }
        return (time) => {
          const z = ((time * 1.1) % 8) - 4;
          raft.position.set(Math.sin(z * 1.4) * 0.35, 0.05 + Math.abs(Math.sin(time * 5)) * 0.05, z);
          raft.rotation.y = time * 0.9;
          raft.rotation.z = Math.sin(time * 4) * 0.05;
        };
      }}
    />
  );
}

import React from 'react';
import { SpaceRings } from './index';

const previews = {
  componentName: 'SpaceRings',
  importPath: 'components/SpaceRings',
  previews: [
    { name: '3D rig', description: "Space rings: gyroscope rings with a strapped-in rider (SRINGS).", render: () => <SpaceRings /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, cyl } from '../Stage';
import { buildPeep } from '../Guest';

// Space rings matched to the RCT2 SRINGS sprite: rust-orange gyroscope rings
// on a simple frame — an outer ring rocks while the inner ring tumbles with a
// strapped-in rider spread-eagle at the centre.
export function SpaceRings() {
  return (
    <Stage
      distance={5.5}
      targetY={1.1}
      build={(t, g) => {
        const RUST = 0xb04a20; // rings (sprite #a04030/#b04020)
        const DARK = 0x6a2f18;
        g.add(cyl(t, 1.3, 1.4, 0.14, 0x8a8f98, [0, 0.07, 0], { tex: 'concrete', repeat: [10, 1], rough: 0.9, seg: 28 }));
        // frame posts holding the outer ring's pivot
        [-1, 1].forEach((s) => {
          g.add(cyl(t, 0.06, 0.08, 1.15, DARK, [s * 1.05, 0.7, 0], { tex: 'metal', metal: 0.4, rough: 0.55, seg: 10 }));
          g.add(cyl(t, 0.1, 0.1, 0.08, RUST, [s * 1.05, 1.28, 0], { rotZ: Math.PI / 2, metal: 0.4, rough: 0.5, seg: 12 }));
        });
        const outer = new t.Group();
        outer.position.y = 1.28;
        g.add(outer);
        const ringO = new t.Mesh(new t.TorusGeometry(0.95, 0.05, 10, 36), new t.MeshStandardMaterial({ color: RUST, metalness: 0.35, roughness: 0.5 }));
        outer.add(ringO);
        const inner = new t.Group();
        outer.add(inner);
        const ringI = new t.Mesh(new t.TorusGeometry(0.72, 0.045, 10, 32), new t.MeshStandardMaterial({ color: 0xd6541a, metalness: 0.35, roughness: 0.5 }));
        ringI.rotation.y = Math.PI / 2;
        inner.add(ringI);
        // rider strapped spread-eagle across the inner ring
        const p = buildPeep(t, { shirt: 0x2f6fd0, seated: false, expression: 'surprised' });
        p.group.scale.setScalar(0.5);
        p.group.position.y = -0.36;
        inner.add(p.group);
        [-0.3, 0.3].forEach((y) => inner.add(cyl(t, 0.02, 0.02, 0.5, 0x24242a, [0, y, 0], { rotZ: Math.PI / 2, metal: 0.5, rough: 0.4, seg: 6 })));
        return (time) => {
          outer.rotation.z = Math.sin(time * 0.9) * 0.7;
          inner.rotation.x = time * 1.7;
        };
      }}
    />
  );
}

import React from 'react';
import { MotionSimulator } from './index';

const previews = {
  componentName: 'MotionSimulator',
  importPath: 'components/MotionSimulator',
  previews: [
    { name: '3D rig', description: "Motion simulator: white pod with pink stripes pitching on hydraulic rams (SIMPOD).", render: () => <MotionSimulator /> },
  ],
};

export default previews;

import React from 'react';
import { Stage, box, cyl } from '../Stage';

// Motion simulator matched to the RCT2 SIMPOD sprite: a WHITE capsule pod with
// PINK racing stripes, mounted on six slate hydraulic rams that pitch and roll
// it through a flight program. Warning chevrons on the base plate.
export function MotionSimulator() {
  return (
    <Stage
      distance={5.5}
      targetY={0.9}
      build={(t, g) => {
        const WHITE = 0xe8ecee; // pod (sprite #e0f0f0)
        const PINK = 0xd6338c;
        const SLATE = 0x54646a; // rams (sprite #608080)
        g.add(box(t, [2.2, 0.18, 2.2], 0x8a8f98, [0, 0.09, 0], { tex: 'concrete', repeat: [7, 7], rough: 0.9 }));
        for (let i = 0; i < 6; i++) g.add(box(t, [0.3, 0.03, 0.14], i % 2 ? 0xe8b020 : 0x1c1c20, [-0.75 + i * 0.3, 0.19, 0.95], { rough: 0.6 })); // chevrons
        const pod = new t.Group();
        pod.position.y = 1.05;
        g.add(pod);
        // hydraulic rams (hexapod layout)
        for (let i = 0; i < 6; i++) {
          const a = (Math.floor(i / 2) / 3) * Math.PI * 2 + (i % 2 ? 0.35 : -0.35);
          const bx = Math.cos(a) * 0.85;
          const bz = Math.sin(a) * 0.85;
          const ram = cyl(t, 0.045, 0.06, 0.95, SLATE, [bx * 0.85, 0.55, bz * 0.85], { tex: 'metal', metal: 0.6, rough: 0.35, seg: 10, rotX: bz * 0.4, rotZ: -bx * 0.4 });
          g.add(ram);
        }
        // pod: layered white capsule + pink stripes + door + vents
        pod.add(box(t, [1.5, 0.75, 1.15], WHITE, [0, 0, 0], { tex: 'plastic', repeat: [4, 2], rough: 0.35 }));
        pod.add(box(t, [1.56, 0.09, 1.2], PINK, [0, -0.18, 0], { rough: 0.45 }));
        pod.add(box(t, [1.56, 0.05, 1.2], PINK, [0, -0.32, 0], { rough: 0.45 }));
        pod.add(box(t, [1.2, 0.4, 0.9], WHITE, [0, 0.5, 0], { tex: 'plastic', repeat: [3, 1], rough: 0.35 })); // cap tier
        pod.add(box(t, [0.36, 0.5, 0.04], 0x2a3236, [0, -0.05, 0.59], { rough: 0.6 })); // door
        pod.add(box(t, [0.3, 0.06, 0.02], 0xe8b020, [0, 0.24, 0.6], { rough: 0.5 })); // sign
        [-0.5, 0.5].forEach((x) => pod.add(box(t, [0.24, 0.16, 0.02], 0x54646a, [x, 0.5, 0.46], { metal: 0.4, rough: 0.5 }))); // vents
        return (time) => {
          pod.rotation.x = Math.sin(time * 1.7) * 0.16;
          pod.rotation.z = Math.sin(time * 1.1 + 1) * 0.14;
          pod.position.y = 1.05 + Math.sin(time * 2.3) * 0.06;
        };
      }}
    />
  );
}

import React from 'react';
import { Chairlift } from './index';

const previews = {
  componentName: 'Chairlift',
  importPath: 'components/Chairlift',
  previews: [
    { name: '3D rig', description: "Chairlift: orange buckets with flags gliding a cable between pylons (CLIFT1).", render: () => <Chairlift /> },
  ],
};

export default previews;

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Chairlift matched to the RCT2 CLIFT1 sprite: ORANGE bucket cabins with a
// little flag on the hanger, gliding along a cable strung between two lattice
// pylons with sheave wheels.
export function Chairlift() {
  return (
    <Stage
      distance={8.5}
      targetY={1.6}
      build={(t, g) => {
        const ORANGE = 0xe8641c;
        const RUN = 6.4;
        const cableY = 2.4;
        // pylons + sheave assemblies
        [-1, 1].forEach((s) => {
          const x = s * (RUN / 2);
          g.add(box(t, [0.5, 0.2, 0.9], 0x8a8f98, [x, 0.1, 0], { tex: 'concrete', repeat: [2, 3], rough: 0.9 }));
          g.add(cyl(t, 0.09, 0.12, cableY, 0x9aa0a8, [x, cableY / 2, 0], { tex: 'metal', metal: 0.5, rough: 0.4, seg: 12 }));
          g.add(box(t, [0.7, 0.1, 0.16], 0x9aa0a8, [x, cableY, 0], { metal: 0.5, rough: 0.4 }));
          [-0.28, 0.28].forEach((o) => g.add(cyl(t, 0.09, 0.09, 0.05, 0x2c2c30, [x + o, cableY - 0.08, 0], { rotX: Math.PI / 2, metal: 0.5, rough: 0.4, seg: 14 }))); // sheaves
        });
        // cable
        g.add(cyl(t, 0.015, 0.015, RUN, 0x3a3a40, [0, cableY - 0.08, 0], { rotZ: Math.PI / 2, metal: 0.7, rough: 0.3, seg: 6 }));
        // buckets
        const buckets: THREE.Group[] = [];
        for (let i = 0; i < 3; i++) {
          const b = new t.Group();
          b.add(cyl(t, 0.015, 0.015, 0.5, 0x3a3a40, [0, -0.25, 0], { metal: 0.6, rough: 0.35, seg: 6 })); // hanger
          b.add(box(t, [0.05, 0.12, 0.02], 0xd6338c, [0.03, -0.06, 0], { rough: 0.6 })); // pink flag
          b.add(cyl(t, 0.3, 0.22, 0.4, ORANGE, [0, -0.68, 0], { tex: 'plastic', repeat: [5, 1], rough: 0.45, seg: 16 })); // bucket
          b.add(cyl(t, 0.32, 0.32, 0.05, 0xc44a14, [0, -0.5, 0], { rough: 0.5, seg: 16 })); // rim
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[(i + 2) % SHIRTS.length], seated: true });
          p.group.scale.setScalar(0.34);
          p.group.position.set(0, -0.98, 0);
          b.add(p.group);
          g.add(b);
          buckets.push(b);
        }
        // ground scenery so the ride reads as transit
        g.add(ball(t, 0.5, 0x6f8f3a, [-1.4, 0.5, 1.4], { tex: 'leaf', repeat: [3, 3], flat: true, rough: 1 }));
        g.add(cyl(t, 0.08, 0.12, 0.8, 0x5a3d22, [-1.4, 0.3, 1.4], { tex: 'wood', repeat: [2, 2], rough: 1, seg: 8 }));
        return (time) => {
          buckets.forEach((b, i) => {
            const x = (((time * 0.7 + i * 2.4) % (RUN + 1.6)) + (RUN + 1.6)) % (RUN + 1.6) - (RUN / 2 + 0.8);
            b.position.set(x, cableY - 0.08, 0);
            b.rotation.z = Math.sin(time * 2 + i) * 0.06; // gentle sway
          });
        };
      }}
    />
  );
}
